examples.setup:
var billing by remember {
    mutableStateOf(
        MonarchAddressAutocompleteAddress(
            line1 = "10 Rua Augusta",
            city = "Lisbon",
            postalCode = "1100-053",
            countryCode = "PT",
        ),
    )
}

examples.code:
@OptIn(ExperimentalMonarchApi::class)
MonarchAddressAutocomplete(
    address = billing,
    onAddressChange = { billing = it },
    search = { emptyList() },
)
